// Bible Advisor service worker: cache-first, fully offline after first load.
// precache-manifest.js is generated by `node tools/build.mjs` and lists every file with a version hash.
importScripts('precache-manifest.js');

const { version, bibleVersion, shell, bible } = self.__PRECACHE;
const SHELL = `ba-shell-${version}`;
const BIBLE = `ba-bible-${bibleVersion}`; // kept across app updates unless the Bible text changes

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL).then((c) => c.addAll(shell)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keep = new Set([SHELL, BIBLE]);
    for (const k of await caches.keys()) if (!keep.has(k)) await caches.delete(k);
    await self.clients.claim();
  })());
});

let bibleJob = null;
async function cacheBible(report) {
  const cache = await caches.open(BIBLE);
  let done = 0;
  const queue = [...bible];
  const worker = async () => {
    while (queue.length) {
      const url = queue.shift();
      if (!(await cache.match(url))) {
        try { const res = await fetch(url, { cache: 'no-cache' }); if (res.ok) await cache.put(url, res); } catch { /* offline: try next time */ }
      }
      done++;
      if (done % 12 === 0 || done === bible.length) report?.(done, bible.length);
    }
  };
  await Promise.all([worker(), worker(), worker(), worker()]);
}

self.addEventListener('message', (event) => {
  const msg = event.data || {};
  if (msg.type === 'cache-bible') {
    const report = async (done, total) => {
      for (const c of await self.clients.matchAll()) c.postMessage({ type: 'bible-progress', done, total });
    };
    bibleJob ??= cacheBible(report).finally(() => { bibleJob = null; });
    event.waitUntil(bibleJob);
  }
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;

  // App navigations always get the cached shell (hash routing).
  if (req.mode === 'navigate') {
    event.respondWith(caches.match('./index.html', { ignoreSearch: true }).then((r) => r || fetch(req)));
    return;
  }
  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && url.pathname.includes('/data/bible/')) {
      const copy = res.clone();
      caches.open(BIBLE).then((c) => c.put(req, copy));
    }
    return res;
  })());
});

// ---------- optional daily reminder (Periodic Background Sync, where supported) ----------
function idbGet(store, key) {
  return new Promise((resolve) => {
    const open = indexedDB.open('bible-advisor', 1);
    open.onerror = () => resolve(undefined);
    open.onsuccess = () => {
      try {
        const req = open.result.transaction(store).objectStore(store).get(key);
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => resolve(undefined);
      } catch { resolve(undefined); }
    };
  });
}
function idbPut(store, key, val) {
  return new Promise((resolve) => {
    const open = indexedDB.open('bible-advisor', 1);
    open.onerror = () => resolve();
    open.onsuccess = () => {
      try { const t = open.result.transaction(store, 'readwrite'); t.objectStore(store).put(val, key); t.oncomplete = () => resolve(); }
      catch { resolve(); }
    };
  });
}

async function maybeRemind() {
  const s = await idbGet('kv', 'settings');
  if (!s || !s.reminder) return;
  const now = new Date();
  const day = now.toISOString().slice(0, 10);
  const [hh, mm] = (s.reminderTime || '08:00').split(':').map(Number);
  if (now.getHours() * 60 + now.getMinutes() < hh * 60 + mm) return;
  if ((await idbGet('kv', 'lastReminder')) === day) return;
  const streak = await idbGet('kv', 'streak');
  const local = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  if (streak && streak.last === local) return; // already read today
  await idbPut('kv', 'lastReminder', day);
  await self.registration.showNotification('Bible Advisor', {
    body: 'Take a quiet minute with God’s Word today.',
    icon: 'icons/icon-192.png', badge: 'icons/favicon-32.png', tag: 'daily', data: { url: './#/home' },
  });
}
self.addEventListener('periodicsync', (event) => { if (event.tag === 'daily-reminder') event.waitUntil(maybeRemind()); });
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: 'window' });
    if (all[0]) { await all[0].focus(); return; }
    await self.clients.openWindow(event.notification.data?.url || './');
  })());
});
